package com.acme.paylens.config;
import com.acme.paylens.employee.*; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component; import java.math.*; import java.util.*;
@Component public class DataSeeder implements CommandLineRunner { private final EmployeeRepository repo; public DataSeeder(EmployeeRepository r){repo=r;}
 public void run(String...a){if(repo.count()>0)return; String[] first={"Ava","Noah","Mia","Liam","Emma","Arjun","Priya","Mateo","Sofia","Ethan","Anaya","Lucas"};String[] last={"Smith","Patel","Garcia","Kim","Brown","Sharma","Nguyen","Wilson","Silva","Mehta"};String[] deps={"Engineering","Product","Finance","Sales","Marketing","HR","Operations","Legal","Customer Success"};String[] countries={"USA","Canada","India","UK","Germany","Australia","Singapore","Brazil"};String[] cur={"USD","CAD","INR","GBP","EUR","AUD","SGD","BRL"};double[] fx={1,0.73,0.012,1.28,1.09,0.66,0.75,0.20};Random rnd=new Random(42);List<Employee> batch=new ArrayList<>(500);
 for(int i=1;i<=10000;i++){int ci=rnd.nextInt(countries.length);String dep=deps[rnd.nextInt(deps.length)];int level=1+rnd.nextInt(6);BigDecimal usd=BigDecimal.valueOf(35000L+level*18000L+rnd.nextInt(45000)).setScale(2);BigDecimal local=usd.divide(BigDecimal.valueOf(fx[ci]),2,RoundingMode.HALF_UP);Employee e=new Employee();e.setEmployeeNumber("ACME-%05d".formatted(i));e.setFirstName(first[rnd.nextInt(first.length)]);e.setLastName(last[rnd.nextInt(last.length)]);e.setEmail("employee"+i+"@acme.com");e.setDepartment(dep);e.setJobTitle((level>=5?"Director":level>=4?"Manager":level>=3?"Senior":"Associate")+" "+dep);e.setCountry(countries[ci]);e.setCurrency(cur[ci]);e.setSalaryAmount(local);e.setNormalizedSalaryUsd(usd);batch.add(e);if(batch.size()==500){repo.saveAll(batch);batch.clear();}} if(!batch.isEmpty())repo.saveAll(batch); System.out.println("Seeded 10,000 employees"); }
}
